const createNoteHandler = async (content?: string) => {

const res = await createNewNote(localStorage.token, {

title: dayjs().format('YYYY-MM-DD'),
data: {
content: {
json: null,
html: content ?? '',
md: content ?? ''
}
},
meta: null,
access_control: {}
}).catch((error) => {
toast.error(`${error}`);
return null;
});

if (res) {
goto(`/notes/${res.id}`);
}
};

const downloadHandler = async (type) => {
console.log('downloadHandler', type);
console.log('selectedNote', selectedNote);
if (type === 'md') {
const blob = new Blob([selectedNote.data.content.md], { type: 'text/markdown' });
saveAs(blob, `${selectedNote.title}.md`);
} else if (type === 'pdf') {
await downloadPdf(selectedNote);
}
};

const downloadPdf = async (note) => {
try {
const [{ default: jsPDF }, { default: html2canvas }] = await Promise.all([
import('jspdf'),
import('html2canvas-pro')
]);


const virtualWidth = 1024;
const virtualHeight = 1400;


const html = note.data?.content?.html ?? '';
let node;
if (html instanceof HTMLElement) {
node = html;
} else {

node = document.createElement('div');
node.innerHTML = html;
document.body.appendChild(node);
}


const canvas = await html2canvas(node, {
useCORS: true,
scale: 2,
width: virtualWidth,
windowWidth: virtualWidth,
windowHeight: virtualHeight
});


if (!(html instanceof HTMLElement)) {
document.body.removeChild(node);
}

const imgData = canvas.toDataURL('image/jpeg', 0.7);


const pdf = new jsPDF('p', 'mm', 'a4');
const imgWidth = 210;
const pageHeight = 297;


const imgHeight = (canvas.height * imgWidth) / canvas.width;
let heightLeft = imgHeight;
let position = 0;

pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
heightLeft -= pageHeight;


while (heightLeft > 0) {
position -= pageHeight;
pdf.addPage();

pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
heightLeft -= pageHeight;
}

pdf.save(`${note.title}.pdf`);
} catch (error) {
console.error('Error generating PDF', error);

toast.error(`${error}`);
}
};

const deleteNoteHandler = async (id) => {
const res = await deleteNoteById(localStorage.token, id).catch((error) => {
toast.error(`${error}`);
return null;
});

if (res) {
init();
}
};

const inputFilesHandler = async (inputFiles) => {


for (const file of inputFiles) {
if (file.type !== 'text/markdown') {
toast.error($i18n.t('Only markdown files are allowed'));
return;
}

const reader = new FileReader();
reader.onload = async (event) => {
const content = event.target.result;
let name = file.name.replace(/\.md$/, '');

if (typeof content !== 'string') {
toast.error($i18n.t('Invalid file content'));
return;
}


const res = await createNewNote(localStorage.token, {
title: name,
data: {
content: {
json: null,
html: marked.parse(content ?? ''),
md: content
}
},
meta: null,
access_control: {}
}).catch((error) => {
toast.error(`${error}`);
return null;
});

if (res) {
init();
}
};

reader.readAsText(file);
}
};

let dragged = false;

const onDragOver = (e) => {
e.preventDefault();


if (e.dataTransfer?.types?.includes('Files')) {
dragged = true;
