const onDrop = async (e) => {
e.preventDefault();
console.log(e);

if (e.dataTransfer?.files) {
const inputFiles = Array.from(e.dataTransfer?.files);
if (inputFiles && inputFiles.length > 0) {
console.log(inputFiles);
inputFilesHandler(inputFiles);
}
}

dragged = false;
};

onDestroy(() => {
