for tool in tools:
name: str = tool["name"]
desc: str = tool.get("description") or ""
input_schema: dict[str, Any] = tool.get("inputSchema") or {}
model = _model_from_schema(name, input_schema)

body: dict[str, Any] = {"tool": name}
