def _has_ui_resource(tool: dict[str, Any]) -> bool:
"""Return True if the tool has a UI resourceUri in its metadata."""
for key in ("meta", "_meta"):
m = tool.get(key)
if isinstance(m, dict):
ui = m.get("ui")
if isinstance(ui, dict) and ui.get("resourceUri"):
return True
return False


